use vstd::prelude::*;

verus! {

fn concat(a: &Vec<u64>, b: &Vec<u64>) -> (res: Vec<u64>)
    requires
        a.len() <= 100,
        b.len() <= 100,
    ensures
        res.len() == a.len() + b.len(),
        // First segment matches `a`
        forall|i: int| 0 <= i < a.len() ==> res[i] == a[i],
        // Second segment matches `b` with shifted index
        forall|i: int|
            a.len() <= i < res.len()
            ==> res[i] == b[i - a.len()],
{
    let mut res: Vec<u64> = Vec::new();

    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            res.len() == i,
            forall|j: int| 0 <= j < i ==> res[j] == a[j],
    {
        res.push(a[i]);
        i += 1;
    }

    let a_len = a.len();
    let mut k: usize = 0;
    while k < b.len()
        invariant
            k <= b.len(),
            res.len() == a_len + k,
            forall|j: int| 0 <= j < a_len ==> res[j] == a[j],
            forall|j: int| a_len <= j < a_len + k ==> res[j] == b[j - a_len],
    {
        res.push(b[k]);
        k += 1;
    }

    res
}

} // verus!